-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per client invoice, drafts and voids included (filter on StatusCode). Needs invoice.view.
CREATE VIEW rpt.Invoice
AS
SELECT
    i.Id AS InvoiceId,
    i.InvoiceNumber AS InvoiceNumber,
    i.ClientId AS ClientId,
    COALESCE(i.ClientName, c.Name) AS ClientName,
    s.Name AS Status,
    s.SystemCode AS StatusCode,
    i.InvoiceDate AS InvoiceDate,
    i.DueDate AS DueDate,
    i.PeriodStart AS PeriodStart,
    i.PeriodEnd AS PeriodEnd,
    i.PoNumber AS PoNumber,
    i.SubTotal AS SubTotal,
    i.TaxAmount AS TaxAmount,
    i.Total AS Total,
    i.AmountPaid AS AmountPaid,
    i.BalanceDue AS BalanceDue,
    IIF((s.SystemCode = 'ISSUED' OR s.SystemCode = 'PARTIAL') AND i.BalanceDue > 0 AND i.DueDate < CAST(SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE tn.TimeZoneId AS DATE), DATEDIFF(DAY, i.DueDate, CAST(SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE tn.TimeZoneId AS DATE)), 0) AS DaysPastDue,
    CAST(i.IssuedAt AS DATE) AS IssuedDate,
    CAST(i.VoidedAt AS DATE) AS VoidedDate
FROM ar.Invoice AS i
JOIN crm.Client AS c ON c.TenantId = i.TenantId AND c.Id = i.ClientId
JOIN lkp.InvoiceStatus AS s ON s.TenantId = i.TenantId AND s.Id = i.InvoiceStatusId
JOIN admin.Tenant AS tn ON tn.Id = i.TenantId
WHERE EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(i.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'invoice.view'));
GO
